package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

/**
 * Restartability classification of a fragment expression. An expression may partially execute before escaping; whether
 * the exact tier may simply re-evaluate the whole expression depends on effects. {@code NOW()} is
 * {@link #QUERY_STABLE}; {@code RAND()}/{@code UUID()} are {@link #VOLATILE}. The conservative default is that
 * {@link #VOLATILE} and {@link #SIDE_EFFECTING_OR_UNSUPPORTED} subtrees are never admitted to a fragment fast path at
 * all — they force full exact-tier evaluation of the enclosing expression.
 */
public enum EffectClass {
	PURE,
	QUERY_STABLE,
	ROW_STABLE,
	VOLATILE,
	SIDE_EFFECTING_OR_UNSUPPORTED;

	/**
	 * Whether re-evaluating the whole expression in the exact tier after a partial fast-path run is observably safe.
	 */
	public boolean restartable() {
		return this == PURE || this == QUERY_STABLE || this == ROW_STABLE;
	}
}
